#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSsiPq: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = SsiPq

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> SsiPq {
        return SsiPq(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: SsiPq) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SsiPq {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: SsiPq, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSsiPq_lift(_ pointer: UnsafeMutableRawPointer) throws -> SsiPq {
    return try FfiConverterTypeSsiPq.lift(pointer)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSsiPq_lower(_ value: SsiPq) -> UnsafeMutableRawPointer {
    return FfiConverterTypeSsiPq.lower(value)
}




public struct Aes256GcmEncryption {
    public var ciphertext: Data
    public var nonce: Data
    public var authTag: Data

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(ciphertext: Data, nonce: Data, authTag: Data) {
        self.ciphertext = ciphertext
        self.nonce = nonce
        self.authTag = authTag
    }
}

#if compiler(>=6)
extension Aes256GcmEncryption: Sendable {}
#endif


extension Aes256GcmEncryption: Equatable, Hashable {
    public static func ==(lhs: Aes256GcmEncryption, rhs: Aes256GcmEncryption) -> Bool {
        if lhs.ciphertext != rhs.ciphertext {
            return false
        }
        if lhs.nonce != rhs.nonce {
            return false
        }
        if lhs.authTag != rhs.authTag {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(ciphertext)
        hasher.combine(nonce)
        hasher.combine(authTag)
    }
}



#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAes256GcmEncryption: FfiConverterRustBuffer {
    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Aes256GcmEncryption {
        return
            try Aes256GcmEncryption(
                ciphertext: FfiConverterData.read(from: &buf), 
                nonce: FfiConverterData.read(from: &buf), 
                authTag: FfiConverterData.read(from: &buf)
        )
    }

    public static func write(_ value: Aes256GcmEncryption, into buf: inout [UInt8]) {
        FfiConverterData.write(value.ciphertext, into: &buf)
        FfiConverterData.write(value.nonce, into: &buf)
        FfiConverterData.write(value.authTag, into: &buf)
    }
}


