public struct FileOperationResult {
    public var outputUri: String
    public var bytesWritten: UInt64
    public var metadataJson: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(outputUri: String, bytesWritten: UInt64, metadataJson: String?) {
        self.outputUri = outputUri
        self.bytesWritten = bytesWritten
        self.metadataJson = metadataJson
    }
}

#if compiler(>=6)
extension FileOperationResult: Sendable {}
#endif


extension FileOperationResult: Equatable, Hashable {
    public static func ==(lhs: FileOperationResult, rhs: FileOperationResult) -> Bool {
        if lhs.outputUri != rhs.outputUri {
            return false
        }
        if lhs.bytesWritten != rhs.bytesWritten {
            return false
        }
        if lhs.metadataJson != rhs.metadataJson {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(outputUri)
        hasher.combine(bytesWritten)
        hasher.combine(metadataJson)
    }
}



