    typealias SwiftType = SsiPqMobileError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SsiPqMobileError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidInput(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Crypto(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Wallet(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Pdf(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Storage(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Io(
            message: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Unavailable(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SsiPqMobileError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidInput(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Crypto(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Wallet(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Pdf(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Storage(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Io(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Unavailable(message):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


